package com.primehr.operations.application;
import com.primehr.config.PrimeHrProperties;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.context.annotation.Configuration;import org.springframework.scheduling.annotation.*;import org.springframework.stereotype.Component;
@Configuration @EnableScheduling @ConditionalOnProperty(name="primehr.reconciliation.scheduling-enabled",havingValue="true") class ReconciliationSchedulingConfiguration {}
@Component @ConditionalOnProperty(name="primehr.reconciliation.scheduling-enabled",havingValue="true") class ReconciliationScheduler {private final OperationsService service;private final PrimeHrProperties properties;ReconciliationScheduler(OperationsService s,PrimeHrProperties p){service=s;properties=p;}@Scheduled(fixedDelayString="${primehr.reconciliation.fixed-delay-millis:86400000}")void run(){String token=properties.reconciliation().serviceToken();if(token.isBlank())throw new IllegalStateException("Scheduled reconciliation requires PRIMEHR_RECONCILIATION_SERVICE_TOKEN");service.run(properties.agency().id(),token.startsWith("Bearer ")?token:"Bearer "+token,"system",null,true);}}
